// break و continue
public class Main {
    public static void main(String[] args) {
        for (int i = 1; i <= 5; i++) {
            // ژمارە جووتەکان دەپەڕێنەوە
            if (i % 2 == 0) {
                continue;
            }
            // کاتێک گەیشتە ٥ لوولەکە دەوەستێت
            if (i == 5) {
                break;
            }
            System.out.println("ژمارە: " + i);
        }
    }
}

